#' Pie Chart (Core, Python)
#'
#' 
#' @param data .
#' @param dep .
#' @param counts .
#' @param subject .
#' @param showCases .
#' @param showPlot .
#' @param label .
#' @param digitsperc .
#' @param resultssubtitle .
#' @param customRatios .
#' @param ratio .
#' @param showExpected .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$missing} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$frequencies} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$gof} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$expected} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cases} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$piePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pyjjpiestats <- function(
    data,
    dep = NULL,
    counts = NULL,
    subject = NULL,
    showCases = FALSE,
    showPlot = TRUE,
    label = "percentage",
    digitsperc = 0,
    resultssubtitle = FALSE,
    customRatios = FALSE,
    ratio = "",
    showExpected = TRUE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyjjpiestats requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(counts)) counts <- jmvcore::resolveQuo(jmvcore::enquo(counts))
    if ( ! missing(subject)) subject <- jmvcore::resolveQuo(jmvcore::enquo(subject))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(counts), counts, NULL),
            `if`( ! missing(subject), subject, NULL))

    for (v in dep) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pyjjpiestatsOptions$new(
        dep = dep,
        counts = counts,
        subject = subject,
        showCases = showCases,
        showPlot = showPlot,
        label = label,
        digitsperc = digitsperc,
        resultssubtitle = resultssubtitle,
        customRatios = customRatios,
        ratio = ratio,
        showExpected = showExpected,
        showConsole = showConsole)

    analysis <- pyjjpiestatsClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

